function kermanentzat_case_media_public_url(string $filename): string
{
    $uploads = wp_upload_dir();
    $url = trailingslashit((string) $uploads['baseurl']) . 'kermanentzat-case-media/' . rawurlencode($filename);

    // Keep media on the current origin. Staging is also reviewed through its
    // internal address, while the public hostname is protected with Basic Auth.
    return wp_make_link_relative($url);
}

function kermanentzat_case_media_track_filename(string $key, string $language): string
{
    $assets = kermanentzat_case_media_assets();
    $file = (string) ($assets[$key]['public_file'] ?? $key);
    return preg_replace('/\.[^.]+$/', '', $file) . '-' . $language . '.vtt';
}

function kermanentzat_case_media_video(string $key, string $language): string
{
    $assets = kermanentzat_case_media_assets();
    $asset = $assets[$key];
    $title = $asset['title'][$language];
    $source = $asset['source'][$language];
    $description = $asset['description'][$language];
    $alt = $asset['alt'][$language];
    $video_url = kermanentzat_case_media_public_url($asset['public_file']);
    $poster_url = kermanentzat_case_media_public_url($asset['poster_file']);
    $class = $asset['aspect'] === 'documentary' ? 'case-media--documentary' : 'case-media--wide';
    $tracks = '';

    foreach (['eu', 'es'] as $track_language) {
        if (($asset['tracks'][$track_language] ?? []) === []) {
            continue;
        }
        $track_url = kermanentzat_case_media_public_url(kermanentzat_case_media_track_filename($key, $track_language));
        $label = $track_language === 'es' ? 'Subtitulos en castellano' : 'Euskarazko azpitituluak';
        $default = $track_language === $language ? ' default' : '';
        $tracks .= '<track kind="captions" src="' . esc_url($track_url) . '" srclang="' . esc_attr($track_language) . '" label="' . esc_attr($label) . '"' . $default . '>';
    }

    return '<figure class="case-media ' . esc_attr($class) . '" id="video-' . esc_attr($key) . '">'
        . '<div class="case-media__frame"><video controls preload="none" playsinline poster="' . esc_url($poster_url) . '" aria-label="' . esc_attr($alt) . '"><source src="' . esc_url($video_url) . '" type="video/mp4">' . $tracks . '</video></div>'
        . '<figcaption><strong>' . esc_html($title) . '</strong><span>' . esc_html($description) . '</span><small>' . esc_html($asset['duration'] . ' · ' . $source) . '</small></figcaption>'
        . '</figure>';
}

function kermanentzat_case_document_block(string $language): string
{
    $assets = kermanentzat_case_media_assets();
    $pdf = $assets['informe'];
    $url = kermanentzat_case_media_public_url($pdf['public_file']);

    if ($language === 'es') {
        return '<section id="documentacion" class="content-band content-band--soft"><div class="content-wrap split-grid"><div><span class="content-label">Documentacion</span><h2 class="section-heading">Informe completo</h2></div><div class="reading-copy"><p class="lead">La familia pone a disposicion el informe <strong>Crimen de Mitika. Agresion mortal a Kerman Villate Beitia</strong> para consultar el analisis completo que contextualiza estos materiales.</p><p>Es un documento de autoria familiar, de 42 paginas y aproximadamente 4,4 MB. Se conserva el PDF original, incluida la discrepancia entre la fecha de portada, 3 de septiembre de 2026, y los pies interiores.</p><div class="document-download"><a class="button button--primary" href="' . esc_url($url) . '" download>Descargar informe</a><a class="button" href="' . esc_url($url) . '">Abrir PDF</a></div></div></div></section>';
    }

    return '<section id="dokumentazioa" class="content-band content-band--soft"><div class="content-wrap split-grid"><div><span class="content-label">Dokumentazioa</span><h2 class="section-heading">Txosten osoa</h2></div><div class="reading-copy"><p class="lead">Familiak <strong>Mitikako krimena. Kerman Villate Beitiaren aurkako hil arteko erasoa</strong> txostena jarri du eskuragarri, material hauek testuinguruan kokatzen dituen analisi osoa kontsultatzeko.</p><p>Familiak egindako dokumentua da, 42 orrialdekoa eta gutxi gorabehera 4,4 MB-koa. Jatorrizko PDFa bere horretan gordetzen da, azaleko dataren, 2026ko irailaren 3aren, eta barruko orri-oineko dataren arteko desadostasuna barne.</p><div class="document-download"><a class="button button--primary" href="' . esc_url($url) . '" download>Deskargatu txostena</a><a class="button" href="' . esc_url($url) . '">Ireki PDFa</a></div></div></div></section>';
}

function kermanentzat_case_media_render_placeholders(string $html, string $language): string
{
    foreach (array_keys(kermanentzat_case_media_assets()) as $key) {
        if ($key === 'informe') {
            continue;
        }
        $html = str_replace(
            "{kermanentzat_case_media_video('{$key}', '{$language}')}",
            kermanentzat_case_media_video($key, $language),
            $html
        );
    }

    return str_replace(
        "{kermanentzat_case_document_block('{$language}')}",
        kermanentzat_case_document_block($language),
        $html
    );
}

function kermanentzat_case_summary_content(string $language, string $caseArt): string
{
    if ($language === 'es') {
        $html = <<<HTML
<header class="page-hero page-hero--case content-band--light">{$caseArt}<div class="content-wrap"><h1>Resumen del caso</h1><p>Qué ocurrió aquella noche, cómo ha evolucionado el proceso y por qué seguimos reclamando verdad, justicia y reparación. Esta página incorpora vídeos aportados por la familia y el <a href="#documentacion">informe completo descargable</a>.</p></div></header>
<section class="content-band content-band--dark"><div class="content-wrap split-grid"><div><h2 class="campaign-heading"><span>Kerman no murió,</span><strong>lo mataron</strong></h2></div><div class="reading-copy"><p class="lead">Kerman Villate Beitia tenía 31 años. En la madrugada del 23 de febrero de 2025, un portero de la discoteca Mitika de Vitoria-Gasteiz le propinó un golpe de una violencia extrema. Esta agresión le produjo la muerte prácticamente de forma inmediata.</p><p>Quienes queríamos a Kerman reclamamos que su muerte se investigue y se juzgue con todas las garantías, y que se depuren las responsabilidades que correspondan.</p></div></div></section>
<section class="content-band content-band--light"><div class="content-wrap split-grid"><div data-reveal><h2 class="section-heading">Qué ocurrió aquella noche</h2></div><div class="reading-copy" data-reveal><p class="lead">Kerman llegó al control de acceso de Mitika junto a sus amigos. Mientras ellos pudieron acceder al hall de Dendaraba, a Kerman le denegaron el paso. Sus amigos intentaron interceder para resolver la situación. Minutos más tarde le dicen a Kerman que entrará en breve y los amigos deciden bajar al local.</p>{kermanentzat_case_media_video('geldiketa', 'es')}<p>Las grabaciones muestran que Kerman permaneció esperando con absoluta tranquilidad y se le ve interactuando con conocidos presentes en la zona. No se observa ninguna actitud agresiva ni situación de tensión por parte de Kerman ni de nadie presente en la zona.</p>{kermanentzat_case_media_video('itxaronaldia', 'es')}<p><strong>Menos de un minuto antes de la agresión</strong>, el responsable del equipo de porteros salió del interior del local y reunió a sus hombres. Tal y como recoge el auto del juez de instrucción, realizó dos gestos señalando de forma evidente la zona de la mandíbula mientras dirigía la mirada hacia el portero que posteriormente agrediría a Kerman. Este respondió simulando un golpe en esa misma zona de su cara y asintiendo con la cabeza.</p>{kermanentzat_case_media_video('prestaketa', 'es')}<p><strong>30 segundos después, y aprovechando la entrada de 2 personas que le servían de pantalla visual, el portero agresor, sin mediar palabra, ni discusión, ni interacción alguna</strong>, golpeó a Kerman con una violencia extrema que terminó provocándole la muerte. La agresión se realizó, a traición, sin ningún motivo aparente, y sin que Kerman pudiese ser consciente de que iba a ser agredido. Tras la agresión, abandonó el lugar caminando hacia el interior del local con total indiferencia.</p>{kermanentzat_case_media_video('erasoa', 'es')}</div></div></section>
<section class="content-band content-band--soft"><div class="content-wrap split-grid"><div data-reveal><h2 class="section-heading">Lo que recogió la instrucción</h2></div><div class="reading-copy" data-reveal><p class="lead"><strong>El Juzgado de Instrucción número 3 de Vitoria-Gasteiz acordó la prisión provisional del portero investigado dos días después del ataque mortal.</strong></p><p>En su resolución de 30 de septiembre de 2025, el juez instructor, ante los indicios sólidos de la gravedad de los hechos, decidió que fuesen enjuiciados por un Tribunal del Jurado como un posible delito de asesinato u homicidio doloso, que es lo que corresponde en estos casos. Para ello valoró, entre otros elementos, la capacidad lesiva del agresor, la zona corporal elegida para el ataque, la forma de ejecución, la ausencia de cualquier enfrentamiento previo y la conducta posterior a la agresión, considerando la concurrencia de una alevosía sorpresiva.</p>{kermanentzat_case_media_video('doloa', 'es')}<p>El informe forense refleja la extrema violencia del impacto. La fuerza del golpe directo recibido por Kerman del agresor le provocó la fractura de ambas mandíbulas y la extracción de un fragmento óseo de aproximadamente 1,5 centímetros, que quedó incrustado en la base de la lengua.</p></div></div></section>
<section class="content-band content-band--light"><div class="content-wrap split-grid"><div data-reveal><h2 class="section-heading">El cambio en el recorrido judicial</h2></div><div class="reading-copy" data-reveal><p class="lead"><strong>El 26 de noviembre de 2025, la Audiencia Provincial de Álava revocó la decisión del juez que había investigado el caso desde el principio.</strong></p><p>Por extraño que pueda parecer, la fiscalía recurrió la decisión del juez instructor incurriendo en graves alteraciones de las evidencias y dando credibilidad a la versión del agresor, pese a que durante la investigación tanto el juez como la Policía Criminalística habían demostrado la falsedad de su relato, incompatible con los hechos documentados. La Audiencia Provincial asumió este relato, rebajó la gravedad de los hechos a un homicidio imprudente en concurso con lesiones dolosas, dejando al agresor en libertad provisional tras pagar una fianza de solo <strong>6.000 euros e impidiendo que sea juzgado por las calificaciones más graves.</strong></p>{kermanentzat_case_media_video('kontakizuna', 'es')}<p><strong>Consideramos que esta actuación no se ajusta a la gravedad de lo ocurrido y supone un profundo desprecio hacia la víctima, su familia y la sociedad en su conjunto.</strong> Al descartar el dolo y la alevosía de forma precipitada en fase intermedia, la Audiencia de Álava invade decisiones que debían haberse adoptado en un juicio con todas las garantías, impidiendo que el hecho sea enjuiciado de forma completa por el jurado que naturalmente le corresponde.</p>{kermanentzat_case_media_video('probintzia_auzitegia', 'es')}<p>La familia recurrió esa decisión, pero el <strong>30 de abril de 2026</strong> el Tribunal Supremo comunicó que no admitía el recurso por un motivo exclusivamente formal. Es decir, el Supremo <strong>no analizó las pruebas ni decidió cómo debían calificarse los hechos.</strong></p><p>Desde la asociación queremos informar a la ciudadanía sobre las irregularidades del proceso e intentar reconducirlo.</p></div></div></section>
<section class="content-band content-band--dark"><div class="content-wrap split-grid"><div><h2 class="section-heading">Advertencias y respuesta institucional</h2></div><div class="reading-copy"><p>Antes de la muerte de Kerman ya existían actuaciones y advertencias relacionadas con la violencia ejercida en el acceso al local. Tras lo sucedido, la familia pidió aclarar qué se conocía, qué medidas se habían adoptado y qué responsabilidades administrativas podían existir.</p><p>El 25 de mayo de 2026, el Ararteko recomendó al Ayuntamiento de Vitoria-Gasteiz que respondiera de manera expresa, motivada e íntegra a la denuncia y que reforzara el control preventivo para garantizar el cumplimiento de las condiciones de seguridad en los locales de ocio.</p><p class="lead">Consideramos insuficiente la respuesta institucional recibida. Trabajamos para que se expliquen las advertencias previas, se revisen las actuaciones realizadas y se adopten medidas que eviten que algo similar vuelva a suceder.</p></div></div></section>
<section class="content-band content-band--soft"><div class="content-wrap split-grid"><div><h2 class="section-heading">Las preguntas de la familia</h2></div><div class="reading-copy"><p class="lead">El informe y las declaraciones familiares plantean preguntas que la familia considera abiertas. Entre ellas, la hipótesis de si la agresión pudo responder a una apuesta o reto, formulada como hipótesis familiar y no como una conclusión judicial.</p>{kermanentzat_case_media_video('apustua', 'es')}</div></div></section>
<section class="content-band content-band--light"><div class="content-wrap split-grid"><div><h2 class="section-heading">Cronología esencial</h2></div><div class="reading-copy"><div class="evidence-list case-timeline">
  <div class="evidence-row"><strong>Mayo de 2024</strong><p>Constan actuaciones y advertencias previas relacionadas con la violencia en el acceso a Mitika. Su alcance sigue formando parte de las cuestiones que reclamamos esclarecer.</p></div>
  <div class="evidence-row"><strong>23-25 de febrero de 2025</strong><p>Kerman murió el 23 de febrero tras recibir el golpe. Dos días después, el juzgado acordó la prisión provisional del portero investigado.</p></div>
  <div class="evidence-row"><strong>30 de septiembre de 2025</strong><p>El juez instructor apreció indicios para un juicio con jurado por homicidio o asesinato.</p></div>
  <div class="evidence-row"><strong>26 de noviembre de 2025</strong><p>Al estimar el recurso de la Fiscalía, la Audiencia Provincial modificó el procedimiento y la calificación provisional, dando la espalda a las conclusiones de la investigación realizada durante la instrucción, y acordó la puesta en libertad bajo fianza del agresor.</p></div>
  <div class="evidence-row"><strong>Enero de 2026</strong><p>La familia recurrió ante el Tribunal Supremo la decisión de la Audiencia Provincial.</p></div>
  <div class="evidence-row"><strong>18 de febrero de 2026</strong><p>Los padres de Kerman comparecieron en el Parlamento Vasco para pedir un juicio con todas las garantías y medidas de prevención.</p></div>
  <div class="evidence-row"><strong>30 de abril de 2026</strong><p>El Tribunal Supremo inadmitió el recurso sin entrar a analizar el fondo del caso.</p></div>
  <div class="evidence-row"><strong>25 de mayo de 2026</strong><p>El Ararteko advirtió al Ayuntamiento de que debió actuar de forma más proactiva ante las reiteradas agresiones registradas en el acceso al local, y le formuló dos recomendaciones: responder de forma motivada a la denuncia presentada por la familia y reforzar los controles preventivos para evitar que se repitan situaciones como estas.</p></div>
  <div class="evidence-row"><strong>Junio de 2026</strong><p>Presentamos Egia Kermanentzat Elkartea y compartimos públicamente el relato, el recorrido del caso y nuestras líneas de trabajo.</p></div>
  <div class="evidence-row"><strong>8 de julio de 2026</strong><p>Expusimos ante la Comisión municipal de Seguridad nuestra valoración de la respuesta del Ayuntamiento y del cumplimiento de las recomendaciones. <strong>El Ayuntamiento no ha cumplido las recomendaciones del Ararteko y ha negado a la familia información que puede ser de gran importancia para el proceso judicial.</strong></p></div>
</div></div></div></section>
{kermanentzat_case_document_block('es')}
